<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/header.php'; $bills=$pdo->query("SELECT b.*,u.full_name,COALESCE((SELECT SUM(amount) FROM payments p WHERE p.bill_id=b.id),0) paid FROM bills b JOIN users u ON u.id=b.cashier_id ORDER BY b.id DESC")->fetchAll();?><h2>Bills Zote</h2><div class="actions"><a class="btn green" href="create.php">+ New Bill</a><a class="btn" href="../prints/bills.php" target="_blank">Print Bills Zote</a></div><table><tr><th>Bill No</th><th>Mteja</th><th>Cashier</th><th>Jumla</th><th>Imelipwa</th><th>Status</th><th>Tarehe</th><th>Action</th></tr><?php foreach($bills as $b):?><tr><td><?=e($b['bill_no'])?></td><td><?=e($b['customer_name']?:'Walk-in')?></td><td><?=e($b['full_name'])?></td><td><?=number_format($b['total'],2)?></td><td><?=number_format($b['paid'],2)?></td><td><?=e($b['status'])?></td><td><?=e($b['created_at'])?></td><td><a class="btn gray" href="../prints/bill.php?id=<?=$b['id']?>" target="_blank">Bill</a> <?php if($b['status']!=='PAID'):?><a class="btn green" href="../payments/pay.php?id=<?=$b['id']?>">Lipa</a><?php endif;?></td></tr><?php endforeach;?></table><?php require_once __DIR__.'/../config/footer.php'; ?>
